__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"PREVIEW_VIDEOS",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"AREA_GUIDE",{enumerable:!0,get:function(){return n}});const t={},n={'Low back':{hook:'Most back pain is not damage. It is an irritated back and a body that stopped moving well.',usually:["Usually nothing is broken or damaged. Lots of people have \"bad\" looking scans and feel totally fine","You did more than your back was ready for, like a big lifting day, long hours sitting, bad sleep or a stressful stretch","A pinched or cranky nerve, if the pain shoots down your leg past the knee","Your hips and core stopped doing their part, so your back picks up the slack"],plan:[['Visit 1','Find what is driving it, treat it hands on with manipulation or dry needling, and give you 3 or 4 moves that calm it down'],['Weeks 2 to 6','Build hip and trunk strength, then load the movements that hurt, like bending and lifting'],['After that','Back to the gym, golf or work without guarding it, with a plan to keep it that way']],timeline:'Most people feel a real change in 2 to 3 weeks',today:{name:'Band pull through',dose:'2 x 12',how:"Anchor a band low behind you, hold it between your legs and face away. Push your hips back, then drive them forward and stand tall. Teaches your hips to lift so your back does not have to."}},Neck:{hook:'Most neck pain comes from a stiff upper back, long days at a screen, and muscles that are working too hard.',usually:["A stiff neck and upper back that make it hard to turn your head","Small neck muscles that get tired, so the bigger ones tighten up. Common after a car accident or long days at a desk","Headaches that actually start in your neck","A cranky nerve, if pain or tingling runs down your arm"],plan:[['Visit 1','Screen out anything serious, then hands on work and dry needling to get you moving'],['Weeks 2 to 6','Deep neck and shoulder blade strength, and setting up your desk and sleep'],['After that','Fewer flare ups and a short routine you can do anywhere']],timeline:'Usually improving within 1 to 3 weeks',today:{name:'Thread the needle',dose:'6 each side',how:"On hands and knees, slide one arm under your body and rotate, then open it toward the ceiling. Exhale into the reach. Frees up the upper back so your neck stops doing the work."}},Shoulder:{hook:'Shoulders usually hurt because the tendons are overloaded or the shoulder blade is not doing its job.',usually:["The shoulder tendons got more work than they were ready for. Usually not a tear, and plenty of people have tears with no pain at all","A frozen shoulder that slowly gets stiff and painful, most common between 40 and 60","A shoulder that feels loose or like it slips out","Pain that is actually coming from your neck"],plan:[['Visit 1','Pin down which tendon or structure it is, settle the pain, and start loading it the right amount'],['Weeks 2 to 8','Progress cuff and shoulder blade strength week by week. Too little does nothing, too much flares it'],['After that','Pressing, throwing and lifting overhead again']],timeline:'Tendons adapt slowly. Expect 6 to 12 weeks for lasting change',today:{name:'Banded external rotation',dose:'3 x 12 each arm',how:"Elbow tucked at your side with a rolled towel under it, rotate your hand out against a light band, then come back slowly. Builds the rotator cuff without irritating it."}},Hip:{hook:'Hip pain is often a strength and control problem we can measure and close.',usually:["Sore tendons on the outside of the hip. It hurts to lie on that side or walk up stairs","A pinch in the front of the hip when you squat deep or sit a long time","Wear and tear in the hip, which gets a lot better with the right strength work","Pain that is actually coming from your low back"],plan:[['Visit 1','Test strength and range side to side, treat what is tight, and start the right loading'],['Weeks 2 to 6','Progressive glute and hip strength, plus how you squat, step and run'],['After that','Running, lifting and sleeping without that ache']],timeline:'Most people notice a change in 3 to 4 weeks',today:{name:'90/90 hip switches',dose:'2 x 8 each side',how:"Sit with both knees bent to 90 degrees, one in front and one to the side. Rotate both knees to the other side and back, staying tall. Use your hands behind you if needed."}},Knee:{hook:'Knees almost always get better with the right load, built up week by week.',usually:["Pain around the kneecap when you ramp up activity faster than your legs can handle","A sore tendon just below the kneecap from running or jumping a lot","Wear and tear (arthritis), where exercise is the first thing that helps, often as much as a shot","Cartilage changes that look scary on an MRI but usually get better with strength work, not surgery"],plan:[['Visit 1','Find the cause and the movements that hurt, and calm it down with load you can tolerate'],['Weeks 2 to 8','Quad and hip strength that ramps up each week, with clear tests to move forward'],['After that','Stairs, squats, running and sport, with a plan to stay there']],timeline:'Expect real progress in 4 to 8 weeks',today:{name:'Spanish squat',dose:'4 x 30 sec hold',how:"Loop a heavy band behind your knees and anchor it in front of you. Sit back into a squat with shins vertical. Loads the quads hard while taking stress off the front of the knee."}},'Ankle or foot':{hook:'Ankles and feet need tendon loading, balance, and a smart return to running.',usually:["Heel pain that is worst with your first steps in the morning","A sore Achilles after you picked up your running or jumping too fast","An old sprain that never fully healed, so your ankle keeps rolling","Weak calves and shaky balance that leave your feet doing too much"],plan:[['Visit 1','Assess the foot and ankle, treat what is irritated, and start tendon loading'],['Weeks 2 to 8','Calf strength, balance and hopping progressions'],['After that','A return to running or sport that does not set you back']],timeline:'Tendons take time. Plan on 6 to 12 weeks',today:{name:'Banded tibialis raises',dose:'2 x 15',how:"Sit with your leg out straight and a band around the top of your foot, anchored in front. Pull your toes toward your shin, then lower slowly over 3 seconds. Builds the shin muscle runners always forget."}},Elbow:{hook:'Most elbow pain is a tendon that got more work than it was ready for. Tendons get better with the right load, not rest.',usually:["Tennis elbow, on the outside, from gripping, typing or lifting palm down","Golfer's elbow, on the inside, from gripping and lifting palm up","A cranky nerve, if tingling runs into your pinky","Pain that starts in your neck or shoulder"],plan:[['Visit 1','Test grip and strength with numbers and start the right tendon loading'],['Weeks 2 to 8','Build forearm and shoulder strength week by week'],['After that','Lifting, golf and work without that ache']],timeline:'Tendons take time. Most people feel a change in 4 to 6 weeks',today:{name:'Isometric wrist extension',dose:'5 x 30 seconds',how:'Forearm supported, palm down. Push the back of your hand up into your other hand and hold.'}},'Wrist or hand':{hook:'Wrist and hand pain usually comes from an irritated nerve or tendon, and both respond well to the right plan.',usually:["Carpal tunnel, with numbness or tingling that is worse at night","Sore thumb tendons from lifting kids or heavy phone use","A wrist that is overloaded from pushups, typing or tools","Symptoms that actually start in your neck"],plan:[['Visit 1','Test the nerve, grip and neck, and calm it down'],['Weeks 2 to 6','Build grip and wrist strength, and fix the positions that set it off'],['After that','Typing, lifting and sleeping without it bugging you']],timeline:'Most people notice a change in 2 to 4 weeks',today:{name:'Wrist and finger motion',dose:'2 x 10 each way',how:'Make a fist, open wide, bend your wrist up and down. Slow and easy.'}},'Mid back':{hook:'A stiff mid back makes your neck and low back do its job. Getting it moving usually feels good fast.',usually:["Hours of sitting that stiffen the upper back","A rib joint that catches when you twist or breathe deep","Weak upper back muscles that tire out by the end of the day","Pain that is coming from your neck"],plan:[['Visit 1','Find the stiff levels and treat them hands on'],['Weeks 2 to 6','Upper back strength and mobility, and your desk and sleep setup'],['After that','Long days at a desk without that knot']],timeline:'Usually improving within 1 to 3 weeks',today:{name:'Thread the needle',dose:'6 each side',how:'On hands and knees, slide one arm under your body and rotate, then open it toward the ceiling.'}},Head:{hook:'Most headaches and dizziness I see are very treatable. Many start in the neck or the inner ear, not the head.',usually:["Headaches that start in the top of the neck","Tension headaches from long days, stress and screens","BPPV, loose crystals in the inner ear that cause short spins","A balance system that needs retraining after a virus"],plan:[['Visit 1','Screen out anything serious, then test the neck and inner ear to find the source'],['Weeks 2 to 6','Treat the source hands on, plus neck strength or balance retraining'],['After that','Fewer headache days and steady on your feet']],timeline:'BPPV often clears in 1 or 2 visits. Headaches usually ease in 2 to 6 weeks',today:{name:'Chin tucks',dose:'2 x 10, hold 3 seconds',how:'Sit tall and glide your chin straight back, like making a double chin.'}},'After surgery':{hook:'After surgery, the right plan follows your surgeon\u2019s protocol and gets you further than the protocol alone.',usually:["Swelling and pain that make your muscles shut off, especially your thigh after knee surgery","Stiffness that sets in if you do not get moving early, in the way your surgeon allows","One side much weaker than the other, which raises the chance of getting hurt again","Going back to sports because enough time passed, not because you passed real strength tests"],plan:[['Visit 1','Review your protocol and restrictions, and set the plan with clear goals for each stage'],['Each stage','Restore motion, then strength, then the activities that matter to you'],['Return','Testable criteria for getting back to sport or full activity, not just the calendar']],timeline:'Follows your surgeon\u2019s timeline. Usually 3 to 9 months',today:{name:'Train the other side',dose:'Your usual sets on the non surgical side',how:"Strength training your healthy limb keeps strength in the surgical side through cross education. Get your surgeon's OK, then train the good side normally."}},'Sport performance':{hook:'Performance starts with how you move. Most people are leaving strength and easy movement on the table.',usually:["Ramping up training too fast, one of the biggest causes of overuse injuries","One side stronger or more powerful than the other","Tight spots that make your body cheat on movements","An old injury that was never fully rehabbed. Your last injury is the best predictor of your next one"],plan:[['Visit 1','A full movement and strength screen with numbers, not guesses'],['Weeks 2 to 8','A program that fits your sport and training schedule, adjusted as you progress'],['Ongoing','Retesting so you can see what changed, plus a full visit when something flares']],timeline:'Measurable gains in 4 to 6 weeks',today:{name:'Hip airplanes',dose:'2 x 5 each side, slow',how:"Stand on one leg in a hinge, then rotate your pelvis open toward the ceiling and back closed. Hold a wall at first. Builds hip control most athletes are missing."}}}},939,[]);
